contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint val1, uint val2) public payable {
        require(val1 != val2);
        require(address(c).balance == 0);

        uint balBefore = address(c).balance;

        c.SetMinSum(val1); if (__ESBMC_reverted()) return;
        c.SetMinSum(val2); if (__ESBMC_reverted()) return;

        assert(c.MinSum() == val2 && address(c).balance == balBefore);
    }
}

